import assert from 'node:assert/strict'
export function ownFixtureHTML({nonce,role,tab}){assert.match(nonce,/^[a-f0-9]{32}$/u);assert(['A','B'].includes(role)&&['A','B'].includes(tab));return`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>QiuYa 同名工作网页</title><style>html,body{margin:0;width:100%;height:100%;font:22px system-ui;background:#eef5f4;color:#153b40}#blue{position:absolute;left:0;top:0;width:50%;height:14%;background:#1687b0}#green{position:absolute;left:50%;top:0;width:50%;height:14%;background:#37aa79}h1{position:absolute;left:10%;top:22%;font-size:30px}#nonce{position:absolute;left:10%;top:39%;font:18px monospace}#entry{position:absolute;left:10%;top:58%;width:60%;height:8%;box-sizing:border-box;padding:12px;border:2px solid #1687b0;border-radius:10px;font:22px system-ui}button{position:absolute;left:72%;top:58%;width:20%;height:8%;border:0;border-radius:10px;background:#1687b0;color:white;font:22px system-ui}#result{position:absolute;left:10%;top:76%}</style><div id="blue"></div><div id="green"></div><h1>隔离工作台 · 聊天${role} · 网页${tab}</h1><div id="nonce">${nonce}</div><form><input id="entry" autocomplete="off" aria-label="本轮中文输入"><button type="submit">确认本单</button></form><p id="result">等待本轮操作</p><script>const nonce='${nonce}',role='${role}',tab='${tab}';const post=value=>fetch('./event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nonce,role,tab,...value})});let moveSequence=0;document.addEventListener('mousemove',e=>{if(e.isTrusted){const sequence=++moveSequence,h=document.querySelector('h1');h.style.color=sequence%2?'#1687b0':'#8e3a70';h.textContent='隔离工作台 · 聊天${role} · 网页${tab} · 移动 '+sequence;post({kind:'mousemove',isTrusted:true,sequence});requestAnimationFrame(()=>requestAnimationFrame(()=>post({kind:'move-painted',isTrusted:true,sequence})))}});document.addEventListener('pointerdown',e=>{if(e.isTrusted)post({kind:'pointerdown',isTrusted:true})});document.querySelector('#entry').addEventListener('input',async e=>{if(!e.isTrusted)return;const b=new TextEncoder().encode(e.target.value),h=await crypto.subtle.digest('SHA-256',b);post({kind:'input',isTrusted:true,valueSHA256:Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join(''),length:e.target.value.length})});document.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();if(!e.isTrusted)return;const value=document.querySelector('#entry').value,b=new TextEncoder().encode(value),h=await crypto.subtle.digest('SHA-256',b);document.querySelector('#result').textContent='已确认本次输入 · '+value;post({kind:'submit',isTrusted:true,valueSHA256:Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join(''),length:value.length})})</script></html>`}
export function admitFixtureEvent(value,{nonce}){assert(value&&typeof value==='object'&&!Array.isArray(value));assert(Object.keys(value).every(k=>['nonce','role','tab','kind','isTrusted','valueSHA256','length','sequence'].includes(k)));assert.equal(value.nonce,nonce);assert(['A','B'].includes(value.role)&&['A','B'].includes(value.tab));assert(['mousemove','move-painted','pointerdown','input','submit'].includes(value.kind));assert.equal(value.isTrusted,true);if(['mousemove','move-painted'].includes(value.kind))assert(Number.isSafeInteger(value.sequence)&&value.sequence>0&&value.sequence<=64);else assert(!Object.hasOwn(value,'sequence'));if(['input','submit'].includes(value.kind)){assert.match(value.valueSHA256,/^[a-f0-9]{64}$/u);assert(Number.isInteger(value.length)&&value.length>0&&value.length<1000)}return structuredClone(value)}
